#include <stdio.h>
#include <stdlib.h>

#define MAX_N 100005

int S_A[MAX_N];
int S_B[MAX_N];

int main() {
    int A, B;
    if (scanf("%d %d", &A, &B) != 2) return 0;

    for (int i = 0; i < A; i++) {
        scanf("%d", &S_A[i]);
    }

    for (int i = 0; i < B; i++) {
        scanf("%d", &S_B[i]);
    }

    int j = 0;
    for (int i = 0; i < A && j < B; i++) {
        if (S_A[i] == S_B[j]) {
            j++;
        }
    }

    if (j == B) {
        printf("S\n");
    } else {
        printf("N\n");
    }

    return 0;
}
